#!/bin/sh
# Create the RLS-constrained runtime role when a fresh PostgreSQL data volume
# is initialized. psql variables and format(%L) keep the password out of SQL
# interpolation (and work with every URL-safe secret generated by the runbook).
set -eu

: "${APP_RW_PASSWORD:?APP_RW_PASSWORD must be set for the db service}"

psql -v ON_ERROR_STOP=1 \
  --username "$POSTGRES_USER" \
  --dbname "$POSTGRES_DB" \
  --set=app_rw_password="$APP_RW_PASSWORD" <<'SQL'
SELECT pg_catalog.format(
  'CREATE ROLE app_rw LOGIN PASSWORD %L NOBYPASSRLS NOCREATEDB NOCREATEROLE',
  :'app_rw_password'
)
WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'app_rw')
\gexec

GRANT CONNECT ON DATABASE hausverwaltung TO app_rw;
SQL

echo "[db-init] app_rw role ensured."
